293: 
294:     if(hint & DecoderFormat_CODE_128)
295:         newHints |= DecodeHints::CODE_128_HINT;
296: 
297:     if(hint & DecoderFormat_DATA_MATRIX)
298:         newHints |= DecodeHints::DATA_MATRIX_HINT;
299: 
300:     if(hint & DecoderFormat_EAN_8)
301:         newHints |= DecodeHints::EAN_8_HINT;
302: 
303:     if(hint & DecoderFormat_EAN_13)
304:         newHints |= DecodeHints::EAN_13_HINT;
305: 
306:     if(hint & DecoderFormat_ITF)
307:         newHints |= DecodeHints::ITF_HINT;
308: 
309:     if(hint & DecoderFormat_MAXICODE)
310:         newHints |= DecodeHints::MAXICODE_HINT;
311: 
312:     if(hint & DecoderFormat_PDF_417)
313:         newHints |= DecodeHints::PDF_417_HINT;
314: 
315:     if(hint & DecoderFormat_QR_CODE)
316:         newHints |= DecodeHints::QR_CODE_HINT;
317: 
318:     if(hint & DecoderFormat_RSS_14)
319:         newHints |= DecodeHints::RSS_14_HINT;
320: 
321:     if(hint & DecoderFormat_RSS_EXPANDED)
322:         newHints |= DecodeHints::RSS_EXPANDED_HINT;
323: 
324:     if(hint & DecoderFormat_UPC_A)
325:         newHints |= DecodeHints::UPC_A_HINT;
326: 
327:     if(hint & DecoderFormat_UPC_E)
328:         newHints |= DecodeHints::UPC_E_HINT;
329: 
330:     if(hint & DecoderFormat_UPC_EAN_EXTENSION)
