344: /*!
345:  * \brief getTagRec - returns rectangle containing the tag.
346:  *
347:  * To be able display tag rectangle regardless of the size of the bit matrix rect is in related coordinates [0; 1].
348:  * \param resultPoints
349:  * \param bitMatrix
350:  * \return
351:  */
352: QRectF getTagRect(const QSharedPointer<std::vector<QSharedPointer<ResultPoint>> > &resultPoints, const QSharedPointer<BitMatrix> &bitMatrix)
353: {
354:     if (resultPoints->size() < 2)
355:         return QRectF();
356: 
357:     int matrixWidth = bitMatrix->getWidth();
358:     int matrixHeight = bitMatrix->getHeight();
359:     // 1D barcode
360:     if (resultPoints->size() == 2) {
361:         WhiteRectangleDetector detector(bitMatrix);
362:         std::vector<QSharedPointer<ResultPoint> > resultRectPoints = detector.detect();
363: 
364:         if (resultRectPoints.size() != 4)
365:             return QRectF();
366: 
367:         qreal xMin = qreal((*resultPoints)[0]->getX());
368:         qreal xMax = xMin;
369:         for (int i = 1; i < resultPoints->size(); ++i) {
370:             qreal x = qreal((*resultPoints)[i]->getX());
371:             if (x < xMin)
372:                 xMin = x;
373:             if (x > xMax)
374:                 xMax = x;
375:         }
376: 
377:         qreal yMin = qreal(resultRectPoints[0]->getY());
378:         qreal yMax = yMin;
379:         for (size_t i = 1; i < resultRectPoints.size(); ++i) {
380:             qreal y = qreal(resultRectPoints[i]->getY());
381:             if (y < yMin)
382:                 yMin = y;
383:             if (y > yMax)
384:                 yMax = y;
385:         }
386: 
387:         return QRectF(QPointF(xMin / matrixWidth, yMax / matrixHeight), QPointF(xMax / matrixWidth, yMin / matrixHeight));
388:     }
389: 
390:     // 2D QR code
391:     if (resultPoints->size() == 4) {
392:         qreal xMin = qreal((*resultPoints)[0]->getX());
393:         qreal xMax = xMin;
394:         qreal yMin = qreal((*resultPoints)[0]->getY());
395:         qreal yMax = yMin;
396:         for (int i = 1; i < resultPoints->size(); ++i) {
397:             qreal x = qreal((*resultPoints)[i]->getX());
398:             qreal y = qreal((*resultPoints)[i]->getY());
399:             if (x < xMin)
400:                 xMin = x;
401:             if (x > xMax)
402:                 xMax = x;
403:             if (y < yMin)
404:                 yMin = y;
405:             if (y > yMax)
406:                 yMax = y;
407:         }
408: 
409:         return QRectF(QPointF(xMin / matrixWidth, yMax / matrixHeight), QPointF(xMax / matrixWidth, yMin / matrixHeight));
410:     }
411: 
412:     return QRectF();
413: }
