415: QString QZXing::decodeImage(const QImage &image, int maxWidth, int maxHeight, bool smoothTransformation)
416: {
417:     //qDebug() << "Start decoding";
418:     QElapsedTimer t;
419:     t.start();
420:     processingTime = -1;
421:     QSharedPointer<Result> res;
422:     emit decodingStarted();
423: 
424:     if(image.isNull())
425:     {
426:         processingTime = t.elapsed();
427:         emit decodingFinished(false);
428:         //qDebug() << "End decoding 1";
429:         return "";
430:     }
431: 
432:     QSharedPointer<CameraImageWrapper> ciw;
433: 
434:     if ((maxWidth > 0) || (maxHeight > 0))
435:         ciw = CameraImageWrapper::Factory(image, maxWidth, maxHeight, smoothTransformation);
436:     else
437:         ciw = CameraImageWrapper::Factory(image, 999, 999, true);
438: 
439:     QString errorMessage = "Unknown";
440: 
441:     QSharedPointer<LuminanceSource> imageRefOriginal = ciw;
442:     QSharedPointer<LuminanceSource> imageRef = imageRefOriginal;
443:     QSharedPointer<GlobalHistogramBinarizer> binz;
444:     QSharedPointer<BinaryBitmap> bb;
445: 
446:     size_t numberOfIterations = 0;
447:     if (imageSourceFilter & SourceFilter_ImageNormal)
448:         numberOfIterations++;
449:     if (imageSourceFilter & SourceFilter_ImageInverted)
450:         numberOfIterations++;
451: 
452:     //qDebug() << "Iterations: "<< numberOfIterations << ", sourceFilter: " << imageSourceFilter;
453: 
454:     for(size_t i=0; i<numberOfIterations; ++i){
455:         try {
456:             if((numberOfIterations == 1 && (imageSourceFilter & SourceFilter_ImageInverted)) || i == 1) {
457:                 //qDebug() << "Selecting Inverted Luminance source";
458:                 imageRef = QSharedPointer<LuminanceSource>((LuminanceSource*)(new InvertedLuminanceSource(imageRefOriginal)));
459:             }
460:             binz = QSharedPointer<GlobalHistogramBinarizer>( new GlobalHistogramBinarizer(imageRef) );
461:             bb = QSharedPointer<BinaryBitmap>( new BinaryBitmap(binz) );
462: 
463:             DecodeHints hints(static_cast<DecodeHintType>(enabledDecoders));
464: 
465:             if (hints.containsFormat(BarcodeFormat::UPC_EAN_EXTENSION)) {
466:                 hints.setAllowedEanExtensions(allowedExtensions_);
467:             }
468: 
469:             lastDecodeOperationSucceded_ = false;
470:             try {
471:                 //qDebug() << "Decoding phase 1: started";
472:                 res = decoder->decode(bb, hints);
473:                 processingTime = t.elapsed();
474:                 lastDecodeOperationSucceded_ = true;
475:                 break;
476:             } catch(zxing::Exception &/*e*/){
477:                 //qDebug() << "Decoding phase 1: failed";
478:             }
479: 
480:             if(!lastDecodeOperationSucceded_ && tryHarder_ && (tryHarderType & TryHarderBehaviour_ThoroughScanning))
481:             {
482:                 //qDebug() << "Decoding phase 2, thorought scan: starting";
483:                 hints.setTryHarder(true);
484:                 if(hints.containsFormat(BarcodeFormat::UPC_EAN_EXTENSION) &&
485:                         !allowedExtensions_.empty() &&
486:                         !(hints & DecodeHints::PRODUCT_HINT).isEmpty() )
487:                     hints.setAllowedEanExtensions(std::set<int>());
488: 
489:                 try {
490:                     res = decoder->decode(bb, hints);
491:                     processingTime = t.elapsed();
492:                     lastDecodeOperationSucceded_ = true;
493:                     break;
494:                 } catch(zxing::Exception &/*e*/) {
495:                     //qDebug() << "Decoding phase 2, thorought scan: failed";
496:                 }
497:             }
498: 
499:             if (!lastDecodeOperationSucceded_&& tryHarder_ && (tryHarderType & TryHarderBehaviour_Rotate) && bb->isRotateSupported()) {
500:                 QSharedPointer<BinaryBitmap> bbTmp = bb;
501: 
502:                 //qDebug() << "Decoding phase 2, rotate: starting";
503: 
504:                 hints.setTryHarder(true);
505:                 for (int i=0; (i<3 && !lastDecodeOperationSucceded_); i++) {
506:                     QSharedPointer<BinaryBitmap> rotatedImage(bbTmp->rotateCounterClockwise());
507:                     bbTmp = rotatedImage;
508: 
509:                     try {
510:                         res = decoder->decode(rotatedImage, hints);
511:                         processingTime = t.elapsed();
512:                         lastDecodeOperationSucceded_ = true;
513:                         break;
514:                     } catch(zxing::Exception &/*e*/) {
515:                         //qDebug() << "Decoding phase 2, rotate: failed";
516:                     }
517:                 }
518:             }
519:         }
520:         catch(zxing::Exception &e)
521:         {
522:             errorMessage = QString(e.what());
523:             //qDebug() << "Decoding failed: " << errorMessage;
524:         }
525:     }
526: 
527:     if (lastDecodeOperationSucceded_) {
528:         //qDebug() << "Decoding succeeded.";
529:         QString string = QString(res->getText()->getText().c_str());
530:         if (!string.isEmpty() && (string.length() > 0)) {
531:             int fmt = res->getBarcodeFormat().value;
532:             decodedFormat = decoderFormatToString(1<<fmt);
533:             charSet_ = QString::fromStdString(res->getCharSet());
534:             if (!charSet_.isEmpty()) {
535: #if QT_VERSION < QT_VERSION_CHECK(6, 0, 0)
536:                     QTextCodec *codec = QTextCodec::codecForName(res->getCharSet().c_str());
537:                     if (codec)
538:                         string = codec->toUnicode(res->getText()->getText().c_str());
539: #else
540:                     QStringDecoder decoder(res->getCharSet().c_str());
541:                     if(decoder.isValid()) {
542:                         string = decoder.decode(QByteArray(res->getText()->getText().c_str()));
543:                     }
544: #endif
545:             }
546: 
547:             emit tagFound(string);
548:             emit tagFoundAdvanced(string, decodedFormat, charSet_);
549: 
550:             QVariantMap metadataMap = metadataToMap(res->getMetadata());
551:             emit tagFoundAdvanced(string, decodedFormat, charSet_, metadataMap);
552: 
553:             try {
554:                 const QRectF rect = getTagRect(res->getResultPoints(), binz->getBlackMatrix());
555:                 emit tagFoundAdvanced(string, decodedFormat, charSet_, rect);
556:             }catch(zxing::Exception &/*e*/){}
557:         }
558:         processingTime = t.elapsed();
559:         emit decodingFinished(true);
560:         return string;
561:     }
562: 
563:     processingTime = t.elapsed();
564:     emit error(errorMessage);
565:     emit decodingFinished(false);
566:     return "";
567: }
