621:         if (imagePath.startsWith("/"))
622:             imagePath = imagePath.right(imagePath.length() - 1);
623:         QQmlEngine *engine = QQmlEngine::contextForObject(this)->engine();
624:         QQuickImageProvider *imageProvider = dynamic_cast<QQuickImageProvider *>(engine->imageProvider(imageUrl.host()));
625:         QSize imgSize;
