627:     } else {
628:         QFileInfo fileInfo(imagePath);
629:         if (!fileInfo.exists()) {
630:             qDebug() << "[decodeSubImageQML()] The file" << imagePath << "does not exist.";
631:             emit decodingFinished(false);
632:             return "";
633:         }
634:         img = QImage(imagePath);
635:     }
636: 
637:     if (offsetX || offsetY || width || height)
638:         img = img.copy(offsetX, offsetY, width, height);
639:     return decodeImage(img);
640: #else
641:     Q_UNUSED(imageUrl);
642:     Q_UNUSED(offsetX);
643:     Q_UNUSED(offsetY);
644:     Q_UNUSED(width);
645:     Q_UNUSED(height);
646:     return decodeImage(QImage());
647: #endif //QZXING_QML
