666: QImage QZXing::encodeData(const QString &data, const QZXingEncoderConfig &encoderConfig)
667: {
668:     QImage image;
669: 
670:     try {
671:         switch (encoderConfig.format) {
672: #ifdef ENABLE_ENCODER_QR_CODE
673:         case EncoderFormat_QR_CODE:
674:         {
675:             QSharedPointer<qrcode::QRCode> barcode = qrcode::Encoder::encode(
676:                         data.toStdWString(),
677:                         encoderConfig.errorCorrectionLevel == EncodeErrorCorrectionLevel_H ?
678:                             qrcode::ErrorCorrectionLevel::H :
679:                             (encoderConfig.errorCorrectionLevel == EncodeErrorCorrectionLevel_Q ?
680:                                  qrcode::ErrorCorrectionLevel::Q :
681:                                  (encoderConfig.errorCorrectionLevel == EncodeErrorCorrectionLevel_M ?
682:                                       qrcode::ErrorCorrectionLevel::M :
683:                                       qrcode::ErrorCorrectionLevel::L)));
684: 
685:             QSharedPointer<qrcode::ByteMatrix> bytesRef = barcode->getMatrix();
686:             const std::vector< std::vector <zxing::byte> >& bytes = bytesRef->getArray();
687:             const int width = int(bytesRef->getWidth()) + (encoderConfig.border ? 2 : 0);
688:             const int height = int(bytesRef->getHeight()) + (encoderConfig.border ? 2 : 0);
689:             const QRgb black = qRgba(0, 0, 0, encoderConfig.transparent ? 0 : 255);
690:             const QRgb white = qRgba(255, 255, 255, 255);
691: 
692:             image = QImage(width, height, QImage::Format_ARGB32);
693:             image.fill(white);
694: 
695:             int offset = encoderConfig.border ? 1 : 0;
696: 
697:             for (size_t i=0; i<bytesRef->getWidth(); ++i) {
