195:     const int width = getWidth();
196:     const int height = getHeight();
197: 
198:     imageBytes = QSharedPointer<std::vector<zxing::byte>>(new std::vector<zxing::byte>((size_t)height * (size_t)width));
199:     imageBytesPerRow = QSharedPointer<std::vector<QSharedPointer<std::vector<zxing::byte>>>>(new std::vector<QSharedPointer<std::vector<zxing::byte>>>(height));
200:     zxing::byte* m = &(*imageBytes)[0];
