202:     for(int j=0; j<height; j++)
203:     {
204:         QSharedPointer<std::vector<zxing::byte>> line(new std::vector<zxing::byte>(width));
205:         for(int i=0; i<width; i++)
206:         {
207:             pixel = origin.pixel(i,j);
208:             if(needsConvesionToGrayscale)
209:                 pixelGrayscale = gray(qRed(pixel),qGreen(pixel),qBlue(pixel));
210:             else
211:                 pixelGrayscale = pixel & 0xFF;
212:             (*line)[i] = pixelGrayscale;
213:         }
214:         (*imageBytesPerRow)[j] = line;
215: 
216: #if __cplusplus > 199711L
217:         memcpy(m, (*line).data(), width);  ///the below line is also usable
218: #else
219:         memcpy(m, &(*line)[0], width);
220: #endif
221:         m += width * sizeof(zxing::byte);
222:     }
