183: static QImage* rgbDataToGrayscale(const uchar* data, const CaptureRect& captureRect,
184:                                  const int alpha, const int red,
185:                                  const int green, const int blue,
186:                                  const bool isPremultiplied = false)
187: {
188:     const int stride = (alpha < 0) ? 3 : 4;
189: 
190:     const int endX = captureRect.sourceWidth - captureRect.startX - captureRect.targetWidth;
191:     const int skipX = (endX + captureRect.startX) * stride;
192: 
193:     QImage *image_ptr = new QImage(captureRect.targetWidth, captureRect.targetHeight, QImage::Format_Grayscale8);
194:     uchar* pixelInit = image_ptr->bits();
195:     data += (captureRect.startY * captureRect.sourceWidth + captureRect.startX) * stride;
196:     for (int y = 1; y <= captureRect.targetHeight; ++y) {
197: 
198:     //Quick fix for iOS & macOS devices. Will be handled better in the future
199: #if defined(Q_OS_IOS) || defined (Q_OS_MAC) || defined(Q_OS_SAILFISH) || defined(Q_OS_UBUNTUTOUCH)
200:         uchar* pixel = pixelInit + (y - 1) * captureRect.targetWidth;
201: #else
202:         uchar* pixel = pixelInit + (captureRect.targetHeight - y) * captureRect.targetWidth;
203: #endif
204:         for (int x = 0; x < captureRect.targetWidth; ++x) {
205:             uchar r = data[red];
206:             uchar g = data[green];
207:             uchar b = data[blue];
208:             if (isPremultiplied) {
209:                 uchar a = data[alpha];
210:                 r = uchar((uint(r) * 255) / a);
211:                 g = uchar((uint(g) * 255) / a);
212:                 b = uchar((uint(b) * 255) / a);
213:             }
214:             *pixel = gray(r, g, b);
215:             ++pixel;
216:             data += stride;
217:         }
218:         data += skipX;
219:     }
220: 
221:     return image_ptr;
222: }
