224: static void YUV_NV21_TO_RGB(uchar* argb, const uchar* yuv, int width, int height) {
225:     int frameSize = width * height;
226: 
227:     int ii = 0;
228:     int ij = 0;
229:     int di = +1;
230:     int dj = +1;
231: 
232:     int a = 0;
233:     for (int i = 0, ci = ii; i < height; ++i, ci += di) {
234:         for (int j = 0, cj = ij; j < width; ++j, cj += dj) {
235:             int y = (0xff & ((int) yuv[ci * width + cj]));
236:             int v = (0xff & ((int) yuv[frameSize + (ci >> 1) * width + (cj & ~1) + 0]));
237:             int u = (0xff & ((int) yuv[frameSize + (ci >> 1) * width + (cj & ~1) + 1]));
238:             y = y < 16 ? 16 : y;
239: 
240:             int r = (int) (1.164f * (y - 16) + 1.596f * (v - 128));
241:             int g = (int) (1.164f * (y - 16) - 0.813f * (v - 128) - 0.391f * (u - 128));
242:             int b = (int) (1.164f * (y - 16) + 2.018f * (u - 128));
243: 
244:             r = r < 0 ? 0 : (r > 255 ? 255 : r);
245:             g = g < 0 ? 0 : (g > 255 ? 255 : g);
246:             b = b < 0 ? 0 : (b > 255 ? 255 : b);
247: 
248:             argb[a++] = 0xff000000 | (r << 16) | (g << 8) | b;
249:         }
250:     }
251: }
