    QZXingEncoderConfig encoderConfig(format, explicitSize, correctionLevel, border, transparent);

    QString dataTemp(QUrl::fromPercentEncoding(data.toUtf8()));

    QImage result = QZXing::encodeData(dataTemp, encoderConfig);
